// CSD_RATIONALE_BEGIN
// This strategy tracks the visible output (`generated`), whether we are inside a
// constrained SMILES span, the active constrained prefix (`currentConstrainedOut`),
// and a simple step counter used as the token-budget cost. Outside a span it
// generates freely, but if a visible "<<" delimiter is observed it switches into
// constrained mode; if we start outside a span and no delimiter is present yet,
// the strategy explicitly opens one so that the molecular string is produced
// under parser control.
// Inside a span, the strategy uses parser-aware decoding throughout. It chooses
// among a few constrained helpers based on lightweight observations: parser
// narrowness (`ValidTokenCount` / `DeadEndDetection`), repetition in the current
// visible output, and caller-supplied token groups. When the parser state is
// complete it closes the span. If a repair helper is ever needed, rollback keeps
// the constrained prefix parser-valid. This supports valid SMILES generation by
// ensuring every committed inside-span token preserves parser validity.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
// - Outside-span free-generation branch: if EOS is sampled we break without
//   changing constrained state. If a normal token is appended and it is not "<<",
//   we remain outside so the implication is vacuous. If the token is "<<", we set
//   insideConstrainedOut := true and currentConstrainedOut := [], which is valid
//   by the method precondition parser.IsValidPrefix([]). The explicit open branch
//   uses OpenConstrainedSpan, whose result also resets the constrained prefix to
//   [] while entering constrained mode.
// - Complete-prefix branch: CloseConstrainedSpan exits constrained mode, so
//   insideConstrainedOut becomes false and the implication is vacuous.
// - Repair branch: RollbackConstrainedSuffix returns a repaired constrained suffix
//   that is parser-valid, so keeping insideConstrainedOut := true preserves the
//   invariant.
// - Active constrained decoding branches: ConstrainedStep,
//   SafeRepetitionPenaltyStep, GroupBoostedConstrainedStep, and
//   AdaptiveConstrainedStep each return either EOS or a token that preserves
//   parser validity. On non-EOS we commit with AppendConstrainedToken, so the new
//   currentConstrainedOut remains parser-valid.
// progress:
// - UnconstrainedStep consumes one token-step. If EOS is returned, visible output
//   does not grow; otherwise we append exactly one token. Hence visible growth is
//   at most the consumed budget 1, preserving |generated| <= |generatedPrefix| + steps.
// - OpenConstrainedSpan and CloseConstrainedSpan each consume one token-step and
//   append at most one visible delimiter token, so the same linear bound is preserved.
// - RollbackConstrainedSuffix does not consume generation budget and only shrinks
//   or preserves visible output; we still charge one loop step in that branch, so
//   the output-length bound remains true.
// - Each constrained token-selection helper used here consumes one token-step. If
//   it returns EOS we break with no visible growth; otherwise AppendConstrainedToken
//   appends exactly one visible token. Thus visible growth is again at most the
//   consumed token budget.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var openedOnce: bool := insideConstrained || helpers.CountTokenOccurrences(generatedPrefix, "<<") > 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    if !openedOnce {
      var openedGenerated, openedInside, openedCurrent := helpers.OpenConstrainedSpan(lm, generated);
      generated := openedGenerated;
      insideConstrainedOut := openedInside;
      currentConstrainedOut := openedCurrent;
      openedOnce := true;
      steps := steps + 1;
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
        if next == "<<" {
          insideConstrainedOut := true;
          currentConstrainedOut := [];
          openedOnce := true;
        }
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else if helpers.DeadEndDetection(parser, currentConstrainedOut, 1) {
    var rolledGenerated, rolledCurrent := helpers.RollbackConstrainedSuffix(
      parser, generated, currentConstrainedOut
    );
    generated := rolledGenerated;
    insideConstrainedOut := true;
    currentConstrainedOut := rolledCurrent;
    steps := steps + 1;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);
    var next := eosToken;

    if |currentConstrainedOut| > 0 && helpers.TokensSinceLastOccurrence(generated, generated[|generated| - 1]) < 3 {
      next := helpers.SafeRepetitionPenaltyStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, generated, 2.0, eosToken
      );
    } else if validCount <= 4 {
      next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
    } else if validCount <= 12 {
      next := helpers.GroupBoostedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, eosToken
      );
    } else {
      next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken
      );
    }

    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

cost := steps;

